    for (unsigned y=0;y<screen_height;++y) {
        const uint8_t *line=raster[crop_top+y*scan_repeat]+crop_left;
        for(unsigned x=0;x<screen_width;++x) {
            uint8_t c=line[x];
            size_t out=((size_t)y*screen_width+x)*3u;
