                if self.interrupt_due_in == 0 {
                    self.interrupt_due_in = PRT_INT_LATENCY;
                }

                if self.ctl & PRT_MODE == 0 {
                    // clear RST_EN and PRT_EN
                    self.ctl &= 0b1111_1100;
                    break;
                } else {
                    // continuous mode: reload counter
                    self.counter = self.reload;
                }
            }
        }
